// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC1155/IERC1155Receiver.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import "../core/AssetShares.sol";

/// @dev Test-only buyer that reenters AssetShares.tradeShares on ERC-1155 receipt.
contract ReenterShareReceiver is IERC1155Receiver {
    AssetShares public immutable shares;
    uint256 public assetId;
    address public seller;
    uint256 public amount;
    uint256 public pricePerShare;
    bool public forceOnReceive;

    constructor(AssetShares shares_) {
        shares = shares_;
    }

    function arm(uint256 assetId_, address seller_, uint256 amount_, uint256 pricePerShare_) external {
        assetId = assetId_;
        seller = seller_;
        amount = amount_;
        pricePerShare = pricePerShare_;
    }

    function approveUsdc(IERC20 usdc, uint256 value) external {
        usdc.approve(address(shares), value);
    }

    function buy() external {
        shares.tradeShares(assetId, seller, amount, pricePerShare);
    }

    function purchase(uint256 id, uint256 value) external {
        shares.purchaseAssetShares(id, value);
    }

    function enableForceOnReceive() external {
        forceOnReceive = true;
    }

    function onERC1155Received(address, address, uint256, uint256, bytes calldata) external override returns (bytes4) {
        if (forceOnReceive) {
            shares.forcedTransfer(seller, address(this), assetId, amount);
        } else {
            shares.tradeShares(assetId, seller, amount, pricePerShare);
        }
        return this.onERC1155Received.selector;
    }

    function onERC1155BatchReceived(
        address,
        address,
        uint256[] calldata,
        uint256[] calldata,
        bytes calldata
    ) external pure override returns (bytes4) {
        return this.onERC1155BatchReceived.selector;
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return interfaceId == type(IERC1155Receiver).interfaceId || interfaceId == type(IERC165).interfaceId;
    }
}

contracts/periphery/OracleRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@chainlink/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol";
import "../interfaces/IOracleRouter.sol";

/**
 * @title OracleRouter
 * @notice Routes price feed queries to Chainlink aggregators for ETH/USD, USD/GBP, USD/Gold, and FTSE 100
 * @dev Reverts on an invalid, incomplete, or stale Chainlink round rather than returning a bad price
 */
contract OracleRouter is IOracleRouter {
    AggregatorV3Interface public immutable ethUsdFeed;
    AggregatorV3Interface public immutable gbpUsdFeed;
    AggregatorV3Interface public immutable goldUsdFeed;
    AggregatorV3Interface public immutable ftse100Feed;

    constructor(
        address _ethUsdFeed,
        address _gbpUsdFeed,
        address _goldUsdFeed,
        address _ftse100Feed
    ) {
        require(_ethUsdFeed != address(0), "Invalid ETH/USD feed");
        require(_gbpUsdFeed != address(0), "Invalid GBP/USD feed");
        require(_goldUsdFeed != address(0), "Invalid Gold/USD feed");
        require(_ftse100Feed != address(0), "Invalid FTSE 100 feed");

        ethUsdFeed = AggregatorV3Interface(_ethUsdFeed);
        gbpUsdFeed = AggregatorV3Interface(_gbpUsdFeed);
        goldUsdFeed = AggregatorV3Interface(_goldUsdFeed);
        ftse100Feed = AggregatorV3Interface(_ftse100Feed);
    }

    /**
     * @notice Get the latest ETH/USD price
     * @return price The latest ETH/USD price (scaled by feed decimals)
     * @return updatedAt Timestamp of the last update
     */
    function getEthUsdPrice() external view returns (int256 price, uint256 updatedAt) {
        return _latestAnswer(ethUsdFeed);
    }

    /**
     * @notice Get the latest USD/GBP price
     * @return price The latest USD/GBP price (scaled by feed decimals)
     * @return updatedAt Timestamp of the last update
     */
    function getGbpUsdPrice() external view returns (int256 price, uint256 updatedAt) {
        return _latestAnswer(gbpUsdFeed);
    }

    /**
     * @notice Get the latest USD/Gold price
     * @return price The latest USD/Gold price (scaled by feed decimals)
     * @return updatedAt Timestamp of the last update
     */
    function getGoldUsdPrice() external view returns (int256 price, uint256 updatedAt) {
        return _latestAnswer(goldUsdFeed);
    }

    /**
     * @notice Get the latest FTSE 100 index value
     * @return value The latest FTSE 100 index value (scaled by feed decimals)
     * @return updatedAt Timestamp of the last update
     */
    function getFtse100Value() external view returns (int256 value, uint256 updatedAt) {
        return _latestAnswer(ftse100Feed);
    }

    function _latestAnswer(AggregatorV3Interface feed) private view returns (int256 price, uint256 updatedAt) {
        (
            uint80 roundId,
            int256 answer,
            uint256 startedAt,
            uint256 timestamp,
            uint80 answeredInRound
        ) = feed.latestRoundData();
        if (answer <= 0) revert InvalidAnswer();
        if (startedAt == 0 || timestamp == 0) revert IncompleteRound();
        if (answeredInRound < roundId) revert StaleRound();
        price = answer;
        updatedAt = timestamp;
    }
}

